<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';import {useRoute} from 'vue-router';import {get,post,patch} from '../api/client';import type {Model,Building,Room,Residence,Repair} from '../api/types';import {notify,errorText,dateTime} from '../ui';import Icon from '../components/Icon.vue';import Drawer from '../components/Drawer.vue';import Pagination from '../components/Pagination.vue';
const route=useRoute(),tab=ref<'rooms'|'buildings'>('rooms'),buildings=ref<Building[]>([]),items=ref<Room[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref('');const filters=reactive({q:String(route.query.q||''),buildingId:'',status:''});
const modal=ref<'room'|'building'|'detail'|null>(null),saveBusy=ref(false),formError=ref(''),dirty=ref(false),selectedRoom=ref<Room>(),selectedBuilding=ref<Building>(),history=ref<Residence[]>([]),related=ref<Repair[]>([]);
const form=reactive<Model<'RoomRequest'>>({buildingId:'',roomNo:'',floorNo:1,capacity:4,enabled:true,remark:''});const buildingForm=reactive({code:'',name:'',floorCount:6,enabled:true});
async function load(){busy.value=true;error.value='';try{const [r,b]=await Promise.all([get<Model<'RoomPage'>>('/rooms',{...filters,page:page.value,pageSize:20}),get<Model<'BuildingPage'>>('/buildings',{pageSize:100})]);items.value=r.items;total.value=r.total;buildings.value=b.items;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function search(){page.value=1;void load();}function turn(p:number){page.value=p;void load();}
function editRoom(room?:Room){selectedRoom.value=room;Object.assign(form,{buildingId:room?.buildingId||buildings.value[0]?.id||'',roomNo:room?.roomNo||'',floorNo:room?.floorNo||1,capacity:room?.capacity||4,enabled:room?.enabled??true,remark:room?.remark||'',expectedVersion:room?.version});formError.value='';dirty.value=false;modal.value='room';}
function editBuilding(b?:Building){selectedBuilding.value=b;Object.assign(buildingForm,{code:b?.code||'',name:b?.name||'',floorCount:b?.floorCount||6,enabled:b?.enabled??true});formError.value='';dirty.value=false;modal.value='building';}
async function save(){saveBusy.value=true;formError.value='';try{if(modal.value==='building'){if(selectedBuilding.value)await patch(`/buildings/${selectedBuilding.value.id}`,{...buildingForm,expectedVersion:selectedBuilding.value.version});else await post('/buildings',buildingForm);}else{if(selectedRoom.value)await patch(`/rooms/${selectedRoom.value.id}`,form);else await post('/rooms',form);}dirty.value=false;modal.value=null;notify('档案已保存');await load();}catch(e){formError.value=errorText(e);}finally{saveBusy.value=false;}}
async function detail(room:Room){modal.value='detail';selectedRoom.value=room;formError.value='';history.value=[];related.value=[];try{const [r,h,o]=await Promise.all([get<Room>(`/rooms/${room.id}`),get<Model<'ResidencePage'>>('/residences',{roomId:room.id,pageSize:100}),get<Model<'RepairPage'>>('/repairs',{roomId:room.id,pageSize:10})]);selectedRoom.value=r;history.value=h.items;related.value=o.items;}catch(e){formError.value=errorText(e);}}
onMounted(load);
</script>
<template><div class="page-heading"><div><h1>宿舍档案</h1><p>维护楼栋与房间，让入住名额和服务范围清楚可查。</p></div><div class="page-actions"><button class="btn subtle" @click="editBuilding()"><Icon name="plus"/>新建楼栋</button><button class="btn primary" @click="editRoom()"><Icon name="plus"/>新建房间</button></div></div><div class="tabs"><button :class="{active:tab==='rooms'}" @click="tab='rooms'">房间档案</button><button :class="{active:tab==='buildings'}" @click="tab='buildings'">楼栋档案</button></div><p v-if="error" class="error-banner" role="alert">{{error}}<button @click="load">重新加载</button></p><section v-if="tab==='rooms'" class="panel"><form class="filters" @submit.prevent="search"><label>关键词<input v-model="filters.q" placeholder="房间号 / 楼栋"></label><label>楼栋<select v-model="filters.buildingId"><option value="">全部负责楼栋</option><option v-for="b in buildings" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>状态<select v-model="filters.status"><option value="">全部状态</option><option value="ENABLED">启用</option><option value="DISABLED">停用</option></select></label><button class="btn primary" :disabled="busy">查询</button><button type="button" class="btn" @click="Object.assign(filters,{q:'',buildingId:'',status:''});search()">重置</button></form><p v-if="busy" class="panel-body loading">正在读取房间档案…</p><div class="table-wrap"><table><thead><tr><th>楼栋 / 房间</th><th>楼层</th><th>容量 / 当前入住</th><th>状态</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td><strong>{{r.buildingName}} <span class="num">{{r.roomNo}}</span></strong></td><td>{{r.floorNo}} 层</td><td><span class="num">{{r.occupiedCount}} / {{r.capacity}}</span> 人</td><td><span class="status" :class="r.enabled?'ACTIVE':'INACTIVE'">{{r.enabled?'启用':'停用'}}</span></td><td>{{r.remark||'—'}}</td><td><div class="cell-actions"><button class="text-link" @click="detail(r)">查看</button><button class="text-link" @click="editRoom(r)">编辑</button></div></td></tr><tr v-if="!busy&&!items.length"><td colspan="6" class="empty-state">没有匹配的房间，可调整筛选或新建档案。</td></tr></tbody></table></div><Pagination :page="page" :page-size="20" :total="total" :busy="busy" @change="turn"/></section><section v-else class="panel"><div class="table-wrap"><table><thead><tr><th>楼栋编码</th><th>名称</th><th>楼层数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="b in buildings" :key="b.id"><td class="num">{{b.code}}</td><td>{{b.name}}</td><td>{{b.floorCount}}</td><td>{{b.enabled?'启用':'停用'}}</td><td><button class="text-link" @click="editBuilding(b)">编辑楼栋</button></td></tr><tr v-if="!buildings.length"><td colspan="5" class="empty-state">暂无负责楼栋，请先新建楼栋。</td></tr></tbody></table></div></section><Drawer v-if="modal==='room'||modal==='building'" :title="modal==='room'?(selectedRoom?'编辑房间':'新建房间'):(selectedBuilding?'编辑楼栋':'新建楼栋')" :busy="saveBusy" :dirty="dirty" @close="modal=null"><form class="form" @input="dirty=true" @submit.prevent="save"><template v-if="modal==='room'"><label>所属楼栋 *<select v-model="form.buildingId" required :disabled="!!selectedRoom"><option value="">请选择楼栋</option><option v-for="b in buildings" :key="b.id" :value="b.id">{{b.name}}</option></select></label><div class="form-row"><label>房间号 *<input v-model.trim="form.roomNo" required maxlength="20" placeholder="例如 302"></label><label>楼层 *<input v-model.number="form.floorNo" type="number" min="1" :max="buildings.find(b=>b.id===form.buildingId)?.floorCount||100" required></label></div><label>房间容量 *<input v-model.number="form.capacity" type="number" :min="Math.max(1,selectedRoom?.occupiedCount||0)" max="20" required><small>容量不得小于当前在住人数；已有入住的房间不能停用。</small></label><label class="checkbox"><input v-model="form.enabled" type="checkbox" :disabled="!!selectedRoom?.occupiedCount">启用房间</label><label>备注<textarea v-model.trim="form.remark" maxlength="500"/></label></template><template v-else><label>楼栋编码 *<input v-model.trim="buildingForm.code" required maxlength="20" placeholder="例如 A"></label><label>楼栋名称 *<input v-model.trim="buildingForm.name" required maxlength="80"></label><label>楼层数 *<input v-model.number="buildingForm.floorCount" type="number" min="1" max="100" required></label><label class="checkbox"><input v-model="buildingForm.enabled" type="checkbox">启用楼栋</label><p class="form-note">新建楼栋仅自动授权给当前宿管。停用时服务端校验房间与入住。</p></template><p v-if="formError" class="error-banner" role="alert">{{formError}}</p><button class="btn primary" :disabled="saveBusy">{{saveBusy?'正在保存…':'保存档案'}}</button></form></Drawer><Drawer v-if="modal==='detail'&&selectedRoom" :title="selectedRoom.buildingName+' '+selectedRoom.roomNo" subtitle="房间档案与历史入住" @close="modal=null"><p v-if="formError" class="error-banner">{{formError}}</p><dl class="details"><div><dt>当前入住 / 容量</dt><dd>{{selectedRoom.occupiedCount}} / {{selectedRoom.capacity}} 人</dd></div><div><dt>房间状态</dt><dd>{{selectedRoom.enabled?'启用':'停用'}}</dd></div><div><dt>楼层</dt><dd>{{selectedRoom.floorNo}} 层</dd></div><div><dt>备注</dt><dd>{{selectedRoom.remark||'无'}}</dd></div></dl><section class="detail-section" style="margin-top:26px"><h3>入住历史</h3><div v-for="h in history" :key="h.id" class="description" style="margin-bottom:10px">{{h.studentName}} · {{h.studentNo}}<br>{{dateTime(h.checkedInAt)}} — {{h.checkedOutAt?dateTime(h.checkedOutAt):'当前在住'}}</div><p v-if="!history.length" class="muted">暂无入住记录。</p></section><section class="detail-section"><h3>关联报修</h3><p v-for="r in related" :key="r.id" style="margin-bottom:12px"><RouterLink :to="'/repairs/'+r.id">{{r.title}} →</RouterLink></p><p v-if="!related.length" class="muted">暂无报修记录。</p></section></Drawer></template>
